"""Qwen3-TTS 0.6B Base — P0 voice benchmark on Kaggle T4.

Sections: A hook/storytelling (~30s), B dense science (~35s), C names/numbers (~30s).
Reference voice: our own Kokoro output (no third-party voice).
Metrics: load, per-section RTF, audio duration, peak VRAM, WER, 10-chunk VRAM growth.
"""

import json
import os
import re
import subprocess
import time
import traceback

import subprocess as _sp
_sp.run([__import__("sys").executable, "-m", "pip", "install", "-q", "qwen-tts", "soundfile"], check=False)

OUT = "/kaggle/working"
os.makedirs(f"{OUT}/audio", exist_ok=True)
REF = "/kaggle/working/reference.wav"
_REF_B64 = ""
import base64 as _b64
open(REF, "wb").write(_b64.b64decode(_REF_B64))
REF_TEXT = "Water expands when it freezes, which is why ice floats on a lake."

SECTIONS = {
    "A_hook": "What if the ice beneath your feet could remember the temperature of the entire ocean? In the polar night, seawater freezes slowly, and the ice that forms is not quite frozen water. It is a sponge: a lattice of crystals with pockets of brine trapped inside. As the ice thickens, it pushes that brine out, and the ocean below becomes saltier, colder, and dense enough to sink. That sinking water drives a global conveyor belt that can take a thousand years to complete one loop.",
    "B_dense": "The physics is surprisingly simple. Water expands when it freezes because hydrogen bonds lock into an open hexagonal lattice. That lattice is less dense than liquid water, so ice floats. The same principle explains why lakes freeze from the top down, why ice sheets can insulate the ocean below, and why a warming climate can change the timing of polar mixing. When the ice melts, it releases fresh water, which is less dense and can cap the surface, slowing the overturning circulation.",
    "C_numbers": "Consider the numbers. Earth's inner core is about five thousand two hundred degrees Celsius. A light-year is about nine point four six trillion kilometers. The human body contains roughly thirty-seven trillion cells. The Mariana Trench is nearly eleven kilometers deep. Voyager 1 is more than twenty-four billion kilometers from Earth. And a teaspoon of neutron star material would weigh about a billion tons.",
}

R = {"status": "ok", "timestamp_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
     "model": "Qwen/Qwen3-TTS-12Hz-0.6B-Base", "sections": {}, "vram_growth": [],
     "wer": {}, "errors": []}


def sh(cmd, timeout=60):
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
    return p.returncode, p.stdout, p.stderr[-1000:]


def dur(path):
    rc, out, _ = sh(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "default=nw=1:nk=1", path])
    try:
        return round(float(out.strip()), 3)
    except ValueError:
        return 0.0


def norm(t):
    t = t.lower()
    t = re.sub(r"[^a-z0-9\s]", " ", t)
    return re.sub(r"\s+", " ", t).strip()


try:
    import torch
    import soundfile as sf
    from qwen_tts import Qwen3TTSModel
    import numpy as np

    assert os.path.exists(REF), f"reference missing: {REF}"
    t0 = time.time()
    model = Qwen3TTSModel.from_pretrained(
        "Qwen/Qwen3-TTS-12Hz-0.6B-Base",
        device_map="cuda:0",
        dtype=torch.bfloat16,
        attn_implementation="sdpa",
    )
    R["load_s"] = round(time.time() - t0, 2)
    R["device"] = torch.cuda.get_device_name(0)
    R["vram_total_gb"] = round(torch.cuda.get_device_properties(0).total_memory / 1024**3, 2)

    files = []
    for name, text in SECTIONS.items():
        path = f"{OUT}/audio/qwen_{name}.wav"
        torch.cuda.reset_peak_memory_stats()
        t0 = time.time()
        wavs, sr = model.generate_voice_clone(text=text, language="English", ref_audio=REF, ref_text=REF_TEXT)
        gen = time.time() - t0
        audio = wavs[0]
        if hasattr(audio, "detach"):
            audio = audio.detach().cpu().numpy()
        audio = np.asarray(audio, dtype=np.float32)
        if audio.ndim > 1:
            audio = audio.mean(axis=1)
        sf.write(path, audio, sr)
        d = dur(path)
        R["sections"][name] = {"text": text, "words": len(text.split()), "file": path,
                               "gen_s": round(gen, 2), "audio_s": d,
                               "rtf": round(gen / d, 3) if d else None,
                               "sample_rate": sr,
                               "peak_vram_mb": round(torch.cuda.max_memory_allocated() / 1024**2, 1)}
        files.append(path)
        print(name, R["sections"][name], flush=True)

    # 10 sequential chunks in one process: VRAM growth check
    for i in range(10):
        wavs, sr = model.generate_voice_clone(text="The ocean remembers.", language="English",
                                              ref_audio=REF, ref_text=REF_TEXT)
        R["vram_growth"].append(round(torch.cuda.max_memory_allocated() / 1024**2, 1))
        print("chunk", i, R["vram_growth"][-1], flush=True)

    # ASR WER
    from faster_whisper import WhisperModel
    from jiwer import wer as jiwer_wer
    from scipy.signal import resample_poly

    asr = WhisperModel("base.en", device="cpu", compute_type="int8")
    for name, path in zip(SECTIONS.keys(), files):
        x, sr = sf.read(path, dtype="float32")
        if x.ndim > 1:
            x = x.mean(axis=1)
        if sr != 16000:
            x = resample_poly(x, 16000, sr)
        segs, _ = asr.transcribe(x, beam_size=1, language="en")
        hyp = norm(" ".join(s.text for s in segs))
        ref = norm(SECTIONS[name])
        R["wer"][name] = {"ref": ref, "hyp": hyp, "wer": round(jiwer_wer(ref, hyp), 4)}
except Exception:
    R["status"] = "error"
    R["errors"].append(traceback.format_exc()[-3000:])

json.dump(R, open(f"{OUT}/QWEN_BENCH.json", "w"), indent=2)
json.dump({"status": R["status"], "errors": R["errors"]}, open(f"{OUT}/DONE.json", "w"), indent=2)
print(json.dumps(R, indent=2)[:4000])